/* ---- assets/js/core/store.js ---- */
/* Data access layer. Every module reads content through these functions, so
   swapping the data files for a CMS or database later only touches this file
   (see README, "Moving to a CMS"). */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var D = J.data;
  var slugify = J.u.slugify;
  var S = (J.store = {});

  var catBySlug = {}, groupBySlug = {}, brandByKey = {}, prodBySlug = {}, artBySlug = {};

  D.groups.forEach(function (g) { groupBySlug[g.slug] = g; });
  D.categories.forEach(function (c) { catBySlug[c.slug] = c; });
  D.brands.forEach(function (b) { b.slug = slugify(b.name); brandByKey[b.slug] = b; });
  D.products.forEach(function (p) { prodBySlug[p.slug] = p; });
  D.articles.forEach(function (a) { artBySlug[a.slug] = a; });

  var TONE = { biology: "green", chemistry: "blue", physics: "indigo", laboratory: "teal" };

  S.groups = function () { return D.groups; };
  S.group = function (slug) { return groupBySlug[slug]; };
  S.categories = function () { return D.categories; };
  S.category = function (slug) { return catBySlug[slug]; };
  S.categoriesIn = function (group) { return D.categories.filter(function (c) { return c.group === group; }); };
  S.homeCategories = function () {
    return D.categories.filter(function (c) { return c.home; }).sort(function (a, b) { return a.home - b.home; });
  };
  S.brands = function () { return D.brands.slice().sort(function (a, b) { return a.name.localeCompare(b.name); }); };
  S.brand = function (key) { return brandByKey[slugify(key)]; };
  S.products = function () { return D.products; };
  S.product = function (slug) { return prodBySlug[slug]; };
  S.articles = function () { return D.articles.slice().sort(function (a, b) { return a.date < b.date ? 1 : -1; }); };
  S.article = function (slug) { return artBySlug[slug]; };
  S.services = function () { return D.services.filter(function (s) { return s.enabled; }); };

  S.tone = function (p) {
    var c = catBySlug[p.category];
    return TONE[c ? c.group : "laboratory"];
  };
  S.toneForCategory = function (c) { return TONE[c.group] || "blue"; };
  S.groupOf = function (p) { var c = catBySlug[p.category]; return c ? c.group : "laboratory"; };

  S.inCategory = function (p, slug) { return p.category === slug || (p.also || []).indexOf(slug) > -1; };
  S.inScope = function (p, scope) {
    if (!scope || scope === "all") return true;
    return S.groupOf(p) === scope;   /* scope is "all" or a subject slug */
  };
  S.productsInCategory = function (slug) { return D.products.filter(function (p) { return S.inCategory(p, slug); }); };
  S.productsByBrand = function (name) { return D.products.filter(function (p) { return p.brand === name; }); };
  S.categoryCount = function (slug) { return S.productsInCategory(slug).length; };
  S.brandCount = function (name) { return S.productsByBrand(name).length; };
  S.featured = function (n, scope) {
    return D.products.filter(function (p) { return p.featured && S.inScope(p, scope); }).slice(0, n || 8);
  };
  S.popular = function (n) { return D.products.filter(function (p) { return p.popular; }).slice(0, n || 8); };

  function take(list, exclude, n) {
    var seen = {}, out = [];
    exclude.forEach(function (p) { seen[p.slug] = 1; });
    list.forEach(function (p) { if (!seen[p.slug] && out.length < n) { seen[p.slug] = 1; out.push(p); } });
    return out;
  }

  /* Similar items: same product type from another brand. */
  S.similarBrands = function (p, n) {
    var same = D.products.filter(function (x) { return x.slug !== p.slug && x.form === p.form && x.brand !== p.brand; });
    return take(same, [p], n || 4);
  };
  S.fromManufacturer = function (p, n) {
    return take(D.products.filter(function (x) { return x.manufacturer === p.manufacturer && x.manufacturer !== "Various manufacturers"; }), [p], n || 4);
  };
  S.related = function (p, n) {
    var skip = [p].concat(S.similarBrands(p, 4), S.fromManufacturer(p, 4));
    var pool = D.products.filter(function (x) { return S.inCategory(x, p.category) || (p.also || []).some(function (c) { return S.inCategory(x, c); }); });
    return take(pool, skip, n || 4);
  };

  /* Option lists for the filters. */
  S.unique = function (field, list) {
    var seen = {};
    (list || D.products).forEach(function (p) { if (p[field]) seen[p[field]] = (seen[p[field]] || 0) + 1; });
    return Object.keys(seen).sort().map(function (k) { return { value: k, count: seen[k] }; });
  };

  S.labels = function () {
    return { composition: "Material or specification", compositionShort: "Spec", strength: "Size or capacity", form: "Product type", pack: "Supplied as" };
  };
  S.storage = function (p) {
    return p.storage || D.storageDefaults[S.groupOf(p)] || D.storageDefaults.laboratory;
  };
})();

/* ---- assets/js/core/search.js ---- */
/* Product search engine: instant, typo-tolerant, runs in the browser.
   - Searches name, brand, alternative name, material, manufacturer, category and type.
   - Every word you type must match something (so "glass funnel" narrows results).
   - Matches exact words, word starts ("micro" → Microscope), and misspellings
     ("beker", "burete"). */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var S = J.store;
  var Q = (J.search = {});

  var FIELDS = [
    ["name", 3], ["brand", 3], ["generic", 2.6], ["composition", 1.6],
    ["manufacturer", 1.2], ["categoryName", 1], ["form", 1], ["pack", 0.4]
  ];
  var SYN = {
    avometer: ["multimeter"], meter: ["meter"], cylinder: ["cylinder"], cyl: ["cylinder"], mic: ["microscope"], micro: ["microscope"],
    bunsen: ["bunsen"], tube: ["tube"], flasks: ["flask"], pipet: ["pipette"], buret: ["burette"], burrette: ["burette"],
    vernier: ["vernier"], caliper: ["caliper"], callipers: ["caliper"], calliper: ["caliper"], slides: ["slide"],
    filter: ["filter"], litmus: ["litmus"], goggle: ["goggles"], coat: ["coat"], scale: ["balance"], weighing: ["balance"],
    petridish: ["petri"], eppendorf: ["centrifuge"]
  };

  function norm(s) {
    return String(s || "").toLowerCase().replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
  }
  function stem(t) { return t.length > 4 && /s$/.test(t) && !/ss$/.test(t) ? t.slice(0, -1) : t; }
  function tokens(s) { return norm(s).split(" ").filter(Boolean).map(stem); }

  /* Damerau-Levenshtein, bounded: returns > max as soon as the distance can't fit. */
  function dist(a, b, max) {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    var prev2 = null, prev = [], cur, i, j;
    for (j = 0; j <= b.length; j++) prev[j] = j;
    for (i = 1; i <= a.length; i++) {
      cur = [i];
      var rowMin = i;
      for (j = 1; j <= b.length; j++) {
        var cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
        var v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
        if (prev2 && i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, prev2[j - 2] + 1);
        cur[j] = v;
        if (v < rowMin) rowMin = v;
      }
      if (rowMin > max) return max + 1;
      prev2 = prev; prev = cur;
    }
    return prev[b.length];
  }

  /* How well does query word q match index word t? 0 = no match. */
  function wordScore(q, t) {
    if (q === t) return 1;
    if (t.indexOf(q) === 0) return q.length >= 2 ? 0.86 : 0.5;
    if (q.length >= 4 && t.indexOf(q) > 0) return 0.55;
    if (q.length >= 4) {
      var max = q.length >= 8 ? 2 : 1;
      var d = dist(q, t.slice(0, Math.max(q.length + 1, 4)), max);
      if (d <= max) return 0.7 - 0.12 * d;
      d = dist(q, t, max);
      if (d <= max) return 0.66 - 0.12 * d;
    }
    return 0;
  }

  var INDEX = null, VOCAB = null;
  function build() {
    var cats = {};
    S.categories().forEach(function (c) { cats[c.slug] = c.name; });
    var vocab = {};
    INDEX = S.products().map(function (p) {
      var doc = { p: p, fields: [] };
      var rec = {
        name: p.name, brand: p.brand === "Generic" ? "" : p.brand, generic: p.generic, composition: p.composition,
        manufacturer: p.manufacturer === "Various manufacturers" ? "" : p.manufacturer,
        categoryName: (cats[p.category] || "") + " " + (p.also || []).map(function (c) { return cats[c] || ""; }).join(" "),
        form: p.form, pack: p.pack
      };
      FIELDS.forEach(function (f) {
        var toks = tokens(rec[f[0]]);
        doc.fields.push({ w: f[1], toks: toks });
        if (f[1] >= 2.6 || f[0] === "form") toks.forEach(function (t) { if (t.length > 2) vocab[t] = (vocab[t] || 0) + 1; });
      });
      return doc;
    });
    S.brands().forEach(function (b) { tokens(b.name).forEach(function (t) { if (t.length > 2) vocab[t] = (vocab[t] || 0) + 1; }); });
    VOCAB = Object.keys(vocab).map(function (t) { return [t, vocab[t]]; });
  }

  function expand(qtokens) {
    var out = [];
    qtokens.forEach(function (t) { if (SYN[t]) SYN[t].forEach(function (x) { out.push(x); }); else out.push(t); });
    return out;
  }

  /* Score one product for a list of query words; 0 if any word fails to match. */
  function scoreDoc(doc, qs) {
    var total = 0;
    for (var i = 0; i < qs.length; i++) {
      var best = 0;
      for (var f = 0; f < doc.fields.length; f++) {
        var fld = doc.fields[f];
        for (var k = 0; k < fld.toks.length; k++) {
          var s = wordScore(qs[i], fld.toks[k]) * fld.w;
          if (k === 0) s *= 1.05;
          if (s > best) best = s;
        }
      }
      if (best === 0) return 0;
      total += best;
    }
    return total;
  }

  /* Public: matches(query) → ordered product list (all products if query is empty). */
  Q.run = function (query) {
    if (!INDEX) build();
    var qs = expand(tokens(query));
    if (!qs.length) return { items: S.products().slice(), didYouMean: "" };
    var hits = [];
    INDEX.forEach(function (doc) {
      var s = scoreDoc(doc, qs);
      if (s > 0) hits.push({ p: doc.p, s: s });
    });
    hits.sort(function (a, b) { return b.s - a.s || a.p.name.localeCompare(b.p.name); });
    return { items: hits.map(function (h) { return h.p; }), didYouMean: hits.length ? "" : Q.didYouMean(query) };
  };

  /* Suggest a corrected phrase when nothing matched. */
  Q.didYouMean = function (query) {
    if (!VOCAB) build();
    var toks = norm(query).split(" ").filter(Boolean);
    var changed = false;
    var fixed = toks.map(function (t) {
      var st = stem(t);
      if (VOCAB.some(function (v) { return v[0] === st; })) return t;
      var best = null, bestD = 99, bestF = 0;
      var max = t.length >= 8 ? 3 : t.length >= 5 ? 2 : 1;
      VOCAB.forEach(function (v) {
        var d = dist(st, v[0], max);
        if (d <= max && (d < bestD || (d === bestD && v[1] > bestF))) { best = v[0]; bestD = d; bestF = v[1]; }
      });
      if (best) { changed = true; return best; }
      return t;
    });
    var phrase = fixed.join(" ");
    return changed && Q.run(phrase).items.length ? phrase : "";
  };

  /* Autocomplete: products first, then brands and categories. */
  Q.suggest = function (query, limit) {
    var res = Q.run(query);
    var qs = tokens(query), out = { products: [], brands: [], categories: [], didYouMean: res.didYouMean };
    if (!qs.length) return out;
    out.products = res.items.slice(0, limit || 6);
    var last = qs.join(" ");
    out.brands = S.brands().filter(function (b) {
      return b.name !== "Generic" && tokens(b.name).some(function (t) { return qs.every(function (q) { return wordScore(q, t) >= 0.86; }); });
    }).slice(0, 2);
    out.categories = S.categories().filter(function (c) {
      return tokens(c.name).some(function (t) { return qs.every(function (q) { return wordScore(q, t) >= 0.86; }); });
    }).slice(0, 2);
    return out;
  };

  /* ---------------- Filters with live facet counts ---------------- */
  Q.FILTERS = ["category", "manufacturer", "brand", "form"];

  function passes(p, f, skip) {
    if (f.category && skip !== "category" && !S.inCategory(p, f.category)) return false;
    if (f.manufacturer && skip !== "manufacturer" && p.manufacturer !== f.manufacturer) return false;
    if (f.brand && skip !== "brand" && p.brand !== f.brand) return false;
    if (f.form && skip !== "form" && p.form !== f.form) return false;
    return true;
  }

  /* state: { q, category, manufacturer, brand, form }; base: products allowed on this page. */
  Q.query = function (state, base) {
    var baseSet = {};
    base.forEach(function (p) { baseSet[p.slug] = 1; });
    var res = Q.run(state.q || "");
    var matched = res.items.filter(function (p) { return baseSet[p.slug]; });
    var items = matched.filter(function (p) { return passes(p, state); });

    function counts(field) {
      var seen = {};
      matched.forEach(function (p) {
        if (!passes(p, state, field)) return;
        if (field === "category") {
          S.categories().forEach(function (c) { if (S.inCategory(p, c.slug)) seen[c.slug] = (seen[c.slug] || 0) + 1; });
        } else if (p[field] && !(field === "manufacturer" && p[field] === "Various manufacturers")) {
          seen[p[field]] = (seen[p[field]] || 0) + 1;
        }
      });
      return seen;
    }
    return { items: items, total: matched.length, didYouMean: res.didYouMean, facets: { category: counts("category"), manufacturer: counts("manufacturer"), brand: counts("brand"), form: counts("form") } };
  };

  /* ---------------- History and popular searches ---------------- */
  var KEY = "jaico.search.history";
  Q.history = function () {
    try { var h = JSON.parse(localStorage.getItem(KEY) || "[]"); return Array.isArray(h) ? h.slice(0, 6) : []; } catch (e) { return []; }
  };
  Q.remember = function (q) {
    q = String(q || "").trim();
    if (q.length < 2) return;
    try {
      var h = Q.history().filter(function (x) { return x.toLowerCase() !== q.toLowerCase(); });
      h.unshift(q);
      localStorage.setItem(KEY, JSON.stringify(h.slice(0, 6)));
    } catch (e) { /* storage blocked: history is optional */ }
  };
  Q.clearHistory = function () { try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ } };
  Q.popular = function () { return J.data.site.hero.popularSearches || []; };
})();

/* ---- assets/js/modules/layout.js ---- */
/* MODULES 1, 2, 15: Header, Navigation, Footer (+ page shell, breadcrumbs, notices).
   Each module returns an HTML string so the same code runs in the browser and
   in the build script that pre-renders the pages. */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var m = (J.m = J.m || {});
  var u = J.u, icon = J.icon, url = J.url, S = J.store;
  var site = function () { return J.data.site; };
  var esc = u.esc;

  var NAV = [
    { key: "home", label: "Home", href: "home" },
    { key: "about", label: "About Us", href: "about" },
    { key: "products", label: "Products", href: "products" },
    { key: "categories", label: "Categories", href: "categories", mega: true },
    { key: "services", label: "Services", href: "services" },
    { key: "contact", label: "Contact Us", href: "contact" }
  ];

  /* ------------------------------------------------------------------ */
  m.brandmark = function (inFooter) {
    var s = site();
    return '<a class="brandmark" href="' + url.page("home") + '" aria-label="' + esc(s.name) + ', home">' +
      J.logo(42) + '<span class="brandmark__text"><span class="brandmark__name">' + esc(s.name) + "</span>" +
      '<span class="brandmark__sub">' + esc(s.tagline) + "</span></span></a>";
  };

  /* ---------------- Search box (shared by header, hero, 404…) ---------------- */
  var sboxCount = 0;
  m.sbox = function (o) {
    o = o || {};
    var id = o.id || "sbox-" + ++sboxCount;
    return '<form class="sbox' + (o.large ? " sbox--lg" : "") + '" role="search" action="' + url.page("search") + '" method="get" data-sbox' +
      (o.stay ? ' data-stay="1"' : "") + ">" +
      '<div class="sbox__field">' + icon("search", 22) +
      '<label class="sr-only" for="' + id + '">Search products, brands and categories</label>' +
      '<input id="' + id + '" class="sbox__input" type="search" name="q" value="' + esc(o.value || "") + '" placeholder="' + esc(o.placeholder || "Search glassware, microscope, burette…") +
      '" autocomplete="off" spellcheck="false" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="' + id + '-list">' +
      '<button type="button" class="sbox__clear" aria-label="Clear search">' + icon("x", 18) + "</button>" +
      '<button class="btn btn--primary' + (o.large ? " btn--lg" : "") + '" type="submit">Search</button></div>' +
      '<div class="sdrop" id="' + id + '-list" role="listbox" aria-label="Search suggestions" hidden></div></form>';
  };

  /* ---------------- Top bar ---------------- */
  m.topbar = function () {
    var s = site(), c = s.contact;
    var pinned = (J.data.announcements.filter(function (a) { return a.pinned; })[0]) || J.data.announcements[0];
    return '<div class="topbar"><div class="container topbar__inner">' +
      '<p class="topbar__notice" data-notice>' + icon("megaphone", 16) + "<span>" + (pinned ? esc(pinned.title) + ". " + esc(pinned.text) : esc(s.tagline)) + "</span></p>" +
      '<div class="topbar__links"><a href="' + link_tel() + '">' + icon("phone", 15) + esc(c.phones[0].display) + "</a>" +
      '<a href="' + J.link.whatsapp() + '" rel="noopener">' + icon("message", 15) + "WhatsApp</a></div></div></div>";
  };
  function link_tel() { return J.link.tel(); }

  /* ---------------- Navigation ---------------- */
  m.megaMenu = function () {
    var cols = S.groups().map(function (g) {
      return "<div><p class=\"mega__title\"><a href=\"" + url.subject(g.slug) + "\">" + esc(g.name) + "</a></p>" + S.categoriesIn(g.slug).map(function (c) {
        return '<a href="' + url.category(c.slug) + '">' + esc(c.name) + "</a>";
      }).join("") + "</div>";
    }).join("");
    return '<div class="mega" id="mega-categories" role="region" aria-label="Browse categories"><div class="mega__cols">' + cols + "</div>" +
      '<div class="mega__foot"><a href="' + url.page("categories") + '">All categories ' + icon("arrowRight", 16) + "</a>" +
      '<a href="' + url.page("brands") + '">Brands ' + icon("arrowRight", 16) + "</a>" +
      '<a href="' + url.page("guides") + '">Lab guides ' + icon("arrowRight", 16) + "</a></div></div>";
  };

  m.nav = function (active) {
    var items = NAV.map(function (n) {
      var cur = n.key === active ? ' aria-current="page"' : "";
      if (n.mega) {
        return '<li class="nav__item" data-mega><button class="nav__link" type="button" aria-expanded="false" aria-controls="mega-categories"' + cur + ">" +
          esc(n.label) + icon("down", 16) + "</button>" + m.megaMenu() + "</li>";
      }
      return '<li class="nav__item"><a class="nav__link" href="' + url.page(n.href) + '"' + cur + ">" + esc(n.label) + "</a></li>";
    }).join("");
    return '<nav class="nav" aria-label="Main"><ul class="nav__list">' + items + "</ul></nav>";
  };

  m.drawer = function (active) {
    var rows = NAV.map(function (n) {
      var cur = n.key === active ? ' aria-current="page"' : "";
      if (n.mega) {
        var subs = S.groups().map(function (g) {
          return '<p class="mega__title"><a href="' + url.subject(g.slug) + '">' + esc(g.name) + "</a></p>" + S.categoriesIn(g.slug).map(function (c) {
            return '<a href="' + url.category(c.slug) + '">' + esc(c.name) + "</a>";
          }).join("");
        }).join("");
        return "<details><summary>" + esc(n.label) + icon("down", 18) + '</summary><div class="drawer__sub">' + subs +
          '<a href="' + url.page("categories") + '"><strong>All categories</strong></a></div></details>';
      }
      return '<a class="drawer__link" href="' + url.page(n.href) + '"' + cur + ">" + esc(n.label) + "</a>";
    }).join("");
    rows += '<a class="drawer__link" href="' + url.page("brands") + '">Brands</a><a class="drawer__link" href="' + url.page("guides") + '">Lab guides</a>';
    return '<div class="drawer" id="drawer" role="dialog" aria-modal="true" aria-label="Menu"><div class="drawer__scrim" data-close-drawer></div>' +
      '<div class="drawer__panel"><div class="drawer__head">' + m.brandmark() +
      '<button class="iconbtn" type="button" data-close-drawer aria-label="Close menu">' + icon("x", 22) + "</button></div>" + rows +
      '<div class="drawer__cta"><a class="btn btn--primary" href="' + J.link.tel() + '">' + icon("phone", 18) + "Call now</a>" +
      '<a class="btn btn--wa" href="' + J.link.whatsapp() + '" rel="noopener">' + icon("message", 18) + "Chat on WhatsApp</a>" +
      '<a class="btn btn--ghost" href="' + J.link.directions() + '" rel="noopener">' + icon("navigation", 18) + "Get directions</a></div></div></div>";
  };

  m.searchOverlay = function () {
    return '<div class="soverlay" id="search-overlay" role="dialog" aria-modal="true" aria-label="Search"><div class="soverlay__panel">' +
      m.sbox({ id: "sbox-overlay", large: true }) + '<p class="soverlay__hint">Press Esc to close. Search by item name, brand, material, size or manufacturer.</p></div></div>';
  };

  m.header = function (active) {
    return '<header class="header" id="top"><div class="container header__inner">' + m.brandmark() + m.nav(active) +
      '<div class="header__tools"><button class="iconbtn" type="button" data-open-search aria-label="Search" aria-haspopup="dialog">' + icon("search", 21) + "</button>" +
      '<button class="iconbtn menu-toggle" type="button" data-open-drawer aria-label="Open menu" aria-haspopup="dialog">' + icon("menu", 22) + "</button></div></div></header>" +
      m.drawer(active) + m.searchOverlay();
  };

  /* ---------------- Footer ---------------- */
  m.footer = function () {
    var s = site(), c = s.contact;
    var quick = [["home", "Home"], ["about", "About us"], ["products", "Products"], ["categories", "Categories"],
      ["brands", "Brands"], ["services", "Services"], ["guides", "Lab guides"], ["contact", "Contact us"]];
    var cats = S.homeCategories().slice(0, 8);
    var phones = c.phones.map(function (p) { return '<a href="tel:' + p.tel + '">' + esc(p.display) + "</a>"; }).join(", ");
    var year = new Date().getFullYear();
    return '<footer class="footer"><div class="container"><div class="footer__grid">' +
      "<div>" + m.brandmark() + '<p class="footer__about">' + esc(s.about.intro[0]) + "</p></div>" +
      "<div><h2>Explore</h2><ul>" + quick.map(function (q) { return '<li><a href="' + url.page(q[0]) + '">' + q[1] + "</a></li>"; }).join("") + "</ul></div>" +
      "<div><h2>Popular categories</h2><ul>" + cats.map(function (x) { return '<li><a href="' + url.category(x.slug) + '">' + esc(x.name) + "</a></li>"; }).join("") + "</ul></div>" +
      '<div><h2>Visit or call</h2><ul class="footer__contact">' +
      "<li>" + icon("pin", 17) + "<span>" + c.addressLines.map(esc).join("<br>") + "</span></li>" +
      "<li>" + icon("phone", 17) + "<span>" + phones + "</span></li>" +
      "<li>" + icon("message", 17) + '<span><a href="' + J.link.whatsapp() + '" rel="noopener">WhatsApp ' + esc(c.whatsapp.display) + "</a></span></li>" +
      "<li>" + icon("mail", 17) + '<span><a href="mailto:' + esc(c.email) + '">' + esc(c.email) + "</a></span></li></ul></div></div>" +
      '<div class="footer__legal"><p>' + esc(s.disclaimers.safety) + "</p><p>" + esc(s.disclaimers.catalogue) + "</p>" +
      '<div class="footer__bottom"><span>&copy; ' + year + " " + esc(s.legalName) + ". All rights reserved.</span>" +
      '<span><a href="' + url.page("privacy") + '">Privacy policy</a>' +
      (s.social.length ? " &nbsp;|&nbsp; " + s.social.map(function (x) { return '<a href="' + esc(x.url) + '" rel="noopener">' + esc(x.label) + "</a>"; }).join(" &nbsp;|&nbsp; ") : "") +
      "</span></div></div></div></footer>" +
      '<nav class="mbar" aria-label="Quick contact"><a href="' + J.link.tel() + '">' + icon("phone", 21) + "Call</a>" +
      '<a href="' + J.link.whatsapp() + '" rel="noopener">' + icon("message", 21) + "WhatsApp</a>" +
      '<a href="' + J.link.directions() + '" rel="noopener">' + icon("navigation", 21) + "Directions</a></nav>";
  };

  /* ---------------- Small shared pieces ---------------- */
  m.crumbs = function (items) {
    return '<nav class="crumbs" aria-label="Breadcrumb">' + items.map(function (it, i) {
      var last = i === items.length - 1;
      return (i ? icon("right", 14) : "") + (last ? '<span aria-current="page">' + esc(it.label) + "</span>" : '<a href="' + it.href + '">' + esc(it.label) + "</a>");
    }).join("") + "</nav>";
  };

  m.pagehead = function (o) {
    return '<section class="pagehead"><div class="container">' + (o.crumbs ? m.crumbs(o.crumbs) : "") +
      "<h1>" + esc(o.title) + "</h1>" + (o.lead ? '<p class="lead">' + esc(o.lead) + "</p>" : "") + (o.extra || "") + "</div></section>";
  };

  m.notice = function (kind) {
    var d = site().disclaimers;
    if (kind === "catalogue") return '<div class="notice notice--blue" role="note">' + icon("info", 20) + "<div><strong>Availability and prices</strong>" + esc(d.catalogue) + "</div></div>";
    return '<div class="notice" role="note">' + icon("alert", 20) + "<div><strong>Safe use</strong>" + esc(d.safety) + "</div></div>";
  };

  m.ctaRow = function (message, opts) {
    opts = opts || {};
    return '<div class="' + (opts.cls || "cta-row") + '"><a class="btn btn--primary' + (opts.lg ? " btn--lg" : "") + '" href="' + J.link.tel() + '">' + icon("phone", 18) + "Call now</a>" +
      '<a class="btn btn--wa' + (opts.lg ? " btn--lg" : "") + '" href="' + J.link.whatsapp(message) + '" rel="noopener">' + icon("message", 18) + "Chat on WhatsApp</a>" +
      (opts.noDirections ? "" : '<a class="btn btn--ghost' + (opts.lg ? " btn--lg" : "") + '" href="' + J.link.directions() + '" rel="noopener">' + icon("navigation", 18) + "Get directions</a>") + "</div>";
  };

  /* ---------------- Page shell ---------------- */
  m.document = function (page) {
    var s = site(), root = J.ctx.root;
    var title = page.title === s.name ? s.name + " | " + s.tagline : page.title + " | " + s.shortName;
    var desc = page.description || s.description;
    var canonical = page.path === "index.html" ? url.abs("") : url.abs(page.path);
    var image = url.abs("assets/img/og-image.png");
    var ld = (page.jsonld || []).map(function (o) { return '<script type="application/ld+json">' + JSON.stringify(o).replace(/</g, "\\u003c") + "</script>"; }).join("\n");
    return "<!doctype html>\n" +
      '<html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
      "<title>" + esc(title) + "</title>" +
      '<meta name="description" content="' + esc(desc) + '">' +
      (page.noindex ? '<meta name="robots" content="noindex">' : '<link rel="canonical" href="' + esc(canonical) + '">') +
      '<meta name="theme-color" content="#1654c9">' +
      '<meta property="og:type" content="' + (page.ogType || "website") + '"><meta property="og:site_name" content="' + esc(s.name) + '">' +
      '<meta property="og:title" content="' + esc(title) + '"><meta property="og:description" content="' + esc(desc) + '">' +
      '<meta property="og:url" content="' + esc(canonical) + '"><meta property="og:image" content="' + esc(image) + '">' +
      '<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:locale" content="en_IN">' +
      '<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="' + esc(title) + '"><meta name="twitter:description" content="' + esc(desc) + '">' +
      '<link rel="icon" href="' + root + 'assets/img/favicon.svg" type="image/svg+xml">' +
      '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' +
      '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&amp;family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&amp;display=swap">' +
      '<link rel="stylesheet" href="' + root + 'assets/css/styles.css">' + ld + "</head>" +
      '<body data-page="' + esc(page.key) + '" data-root="' + root + '"' + (page.attrs || "") + ">" +
      '<a class="skip" href="#main">Skip to main content</a>' +
      '<noscript><p class="noscript">Some features, such as instant search suggestions and filters, need JavaScript. You can still browse every page, call us or message us.</p></noscript>' +
      m.topbar() + m.header(page.nav) + '<main id="main" tabindex="-1">' + page.body + "</main>" + m.footer() +
      '<script src="' + root + 'assets/js/site.bundle.js" defer></script></body></html>';
  };
})();

/* ---- assets/js/modules/products.js ---- */
/* MODULES 4–6: Product search UI, Product catalogue, Product details.
   Product cards never carry price, stock or purchase controls. */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var m = (J.m = J.m || {});
  var u = J.u, icon = J.icon, url = J.url, S = J.store, esc = u.esc;

  var PAGE_SIZE = 24;
  m.PAGE_SIZE = PAGE_SIZE;

  m.productArt = function (p, label) {
    if (p.image) return '<img src="' + url.asset(p.image) + '" alt="' + esc(label || p.name) + '" loading="lazy" width="640" height="480">';
    return J.art(p.art, S.tone(p), label);
  };

  /* Professional product card: image, name, brand, manufacturer, composition, description, View details */
  m.productCard = function (p) {
    var href = url.product(p.slug);
    return '<article class="pcard"><a class="pcard__media" href="' + href + '" tabindex="-1" aria-hidden="true">' + m.productArt(p) + "</a>" +
      '<div class="pcard__body"><div class="pcard__top"><span class="pcard__form">' + esc(p.form) + "</span></div>" +
      '<h3 class="pcard__title"><a href="' + href + '">' + esc(p.name) + "</a></h3>" +
      '<dl class="pcard__facts"><dt>Brand</dt><dd>' + esc(p.brand) + "</dd><dt>Made by</dt><dd>" + esc(u.truncate(p.manufacturer, 34)) + "</dd>" +
      "<dt>" + S.labels(p).compositionShort + "</dt><dd>" + esc(u.truncate(p.composition, 70)) + "</dd></dl>" +
      '<p class="pcard__desc">' + esc(p.description) + "</p>" +
      '<div class="pcard__cta"><a class="btn btn--soft btn--sm btn--block" href="' + href + '">View details<span class="sr-only"> for ' + esc(p.name) + "</span></a></div></div></article>";
  };

  m.productGrid = function (list, cls) {
    return '<div class="pgrid ' + (cls || "") + '">' + list.map(m.productCard).join("") + "</div>";
  };

  m.productItem = function (p) {
    return '<a class="pitem" href="' + url.product(p.slug) + '"><span class="pitem__thumb">' + m.productArt(p) + "</span>" +
      '<span class="pitem__text"><strong>' + esc(p.name) + "</strong><small>" + esc(p.brand) + ", " + esc(p.form) + "</small></span></a>";
  };

  /* Pack-label card used in the hero */
  m.packLabel = function (p) {
    return '<a class="plabel" href="' + url.product(p.slug) + '"><div class="plabel__art">' + m.productArt(p) + "</div>" +
      '<div class="plabel__body"><div class="plabel__top"><span class="pcard__form">' + esc(p.form) + "</span></div>" +
      '<div class="plabel__name">' + esc(p.name) + "</div><dl><dt>Brand</dt><dd>" + esc(p.brand) + "</dd><dt>Made by</dt><dd>" + esc(u.truncate(p.manufacturer, 30)) +
      "</dd><dt>" + S.labels(p).compositionShort + "</dt><dd>" + esc(u.truncate(p.composition, 34)) + "</dd></dl></div></a>";
  };

  /* ------------------------------------------------------------------ */
  /* Catalogue: search box + filters + results.                          */
  /* state: { q, category, manufacturer, brand, form, limit }            */
  /* cfg:   { scope, category (fixed category slug) }                    */
  /* ------------------------------------------------------------------ */
  function baseProducts(cfg) {
    return S.products().filter(function (p) {
      return S.inScope(p, cfg.scope) && (!cfg.category || S.inCategory(p, cfg.category));
    });
  }
  m.catalogueBase = baseProducts;

  function option(value, label, selected) {
    return '<option value="' + esc(value) + '"' + (selected ? " selected" : "") + ">" + esc(label) + "</option>";
  }

  function selectHtml(field, label, allLabel, opts, cur) {
    return '<label class="select"><span>' + esc(label) + '</span><select data-filter="' + field + '" id="f-' + field + '">' +
      option("", allLabel, !cur) + opts + "</select></label>";
  }

  function filtersHtml(state, cfg, res) {
    var f = res.facets, html = "", n = 0;
    function simple(field, label, allLabel) {
      var keys = Object.keys(f[field]);
      if (state[field] && keys.indexOf(state[field]) < 0) keys.push(state[field]);
      keys.sort();
      return selectHtml(field, label, allLabel, keys.map(function (k) { return option(k, k + (f[field][k] ? " (" + f[field][k] + ")" : ""), state[field] === k); }).join(""), state[field]);
    }
    if (!cfg.category) {
      var og = S.groups().map(function (g) {
        var cs = S.categoriesIn(g.slug).filter(function (c) { return f.category[c.slug] || state.category === c.slug; });
        if (!cs.length) return "";
        return '<optgroup label="' + esc(g.name) + '">' + cs.map(function (c) {
          return option(c.slug, c.name + (f.category[c.slug] ? " (" + f.category[c.slug] + ")" : ""), state.category === c.slug);
        }).join("") + "</optgroup>";
      }).join("");
      html += selectHtml("category", "Category", "All categories", og, state.category); n++;
    }
    html += simple("manufacturer", "Manufacturer", "All manufacturers"); n++;
    html += simple("brand", "Brand", "All brands"); n++;
    html += simple("form", "Product type", "All types"); n++;
    return '<div class="filters" style="--n:' + n + '" role="group" aria-label="Filter results">' + html + "</div>";
  }

  function activeHtml(state, cfg) {
    var chips = [];
    function chip(field, text) {
      chips.push('<button type="button" data-clear="' + field + '">' + esc(text) + icon("x", 14) + '<span class="sr-only"> Remove filter</span></button>');
    }
    if (state.q) chip("q", "Search: " + state.q);
    if (state.category && !cfg.category) { var c = S.category(state.category); chip("category", c ? c.name : state.category); }
    if (state.manufacturer) chip("manufacturer", state.manufacturer);
    if (state.brand) chip("brand", "Brand: " + state.brand);
    if (state.form) chip("form", state.form);
    return chips.length ? chips.join("") + '<button type="button" class="link" data-clear="all">Clear all</button>' : "";
  }

  m.catalogueBody = function (state, cfg) {
    state = state || {};
    var res = J.search.query(state, baseProducts(cfg));
    var limit = state.limit || PAGE_SIZE;
    var shown = res.items.slice(0, limit);
    var noun = "product";
    var html = filtersHtml(state, cfg, res);
    html += '<div class="results__bar"><p class="results__count">' + (res.items.length === res.total && !activeHtml(state, cfg) ? "Showing " : "") +
      u.plural(res.items.length, noun) + (state.q ? " for “" + esc(state.q) + "”" : "") + '</p><div class="active">' + activeHtml(state, cfg) + "</div></div>";
    if (!res.items.length) {
      html += '<div class="empty"><h3>' + (state.q ? "No " + noun + "s match “" + esc(state.q) + "”" : "Nothing matches these filters") + "</h3>" +
        "<p>" + (res.didYouMean ? 'Did you mean <button type="button" class="link-btn" data-suggest="' + esc(res.didYouMean) + '">' + esc(res.didYouMean) + "</button>? " : "") +
        "Check the spelling or clear a filter. We may still stock it, so you can also call or message us.</p>" +
        '<div class="cta-row" style="justify-content:center">' +
        '<button type="button" class="btn btn--soft" data-clear="all">Clear search and filters</button>' +
        '<a class="btn btn--wa" href="' + J.link.whatsapp("Hello, I am looking for " + (state.q || "a product") + ".") + '" rel="noopener">' + icon("message", 18) + "Ask on WhatsApp</a></div></div>";
    } else {
      html += m.productGrid(shown);
      if (res.items.length > shown.length) {
        html += '<div class="loadmore"><button type="button" class="btn btn--ghost" data-more>Show more (' + (res.items.length - shown.length) + " left)</button></div>";
      }
    }
    return { html: html, count: res.items.length };
  };

  m.catalogue = function (cfg, state) {
    state = state || {};
    var body = m.catalogueBody(state, cfg);
    return '<div class="catalogue" data-catalogue data-scope="' + esc(cfg.scope || "all") + '"' + (cfg.category ? ' data-category="' + esc(cfg.category) + '"' : "") + ">" +
      '<div class="cattools">' + m.sbox({ id: "cat-q", stay: true, value: state.q, placeholder: "Search items, brands, materials…" }) + "</div>" +
      '<p class="sr-only" role="status" aria-live="polite" data-cat-live></p>' +
      '<div data-cat-body>' + body.html + "</div></div>";
  };

  /* ------------------------------------------------------------------ */
  /* Product detail                                                       */
  /* ------------------------------------------------------------------ */
  m.productDetail = function (p) {
    var L = S.labels(p), s = J.data.site;
    var cat = S.category(p.category);
    var backPage = "products";
    var rows = [["Brand", '<a href="' + url.brand(p.brand) + '">' + esc(p.brand) + "</a>"]];
    if (p.generic) rows.push(["Also called", esc(p.generic)]);
    rows.push([L.composition, esc(p.composition)]);
    rows.push([L.strength, esc(p.strength)]);
    rows.push([L.form, esc(p.form)]);
    rows.push([L.pack, esc(p.pack)]);
    rows.push(["Manufacturer", p.manufacturer === "Various manufacturers" ? esc(p.manufacturer) :
      '<a href="' + url.page(backPage) + "?manufacturer=" + encodeURIComponent(p.manufacturer) + '">' + esc(p.manufacturer) + "</a>"]);
    if (cat) rows.push(["Category", '<a href="' + url.category(cat.slug) + '">' + esc(cat.name) + "</a>"]);

    var ask = "Hello, I would like to check availability of " + p.name + (p.pack ? " (" + p.pack + ")" : "") + ".";
    var html = '<section class="section section--tight"><div class="container">' +
      m.crumbs([{ label: "Home", href: url.page("home") }, { label: "Products", href: url.page(backPage) },
        { label: cat ? cat.name : "Category", href: url.category(p.category) }, { label: p.name }]) +
      '<div class="pdp"><div><div class="pdp__media">' + m.productArt(p, p.name + " (illustration)") + "</div>" +
      (p.image ? "" : '<p class="muted" style="font-size:.84rem;margin-top:10px">Illustration. The actual pack may look different.</p>') + "</div>" +
      '<div class="pdp__info"><div class="pdp__badges">' + (cat ? '<span class="badge badge--na">' + esc(cat.name) + "</span>" : "") + "</div>" +
      "<h1>" + esc(p.name) + '</h1><p class="pdp__sub">' + esc(p.brand) + (p.manufacturer !== "Various manufacturers" ? ", made by " + esc(p.manufacturer) : "") + "</p>" +
      '<p class="pdp__desc">' + esc(p.description) + "</p>" +
      '<dl class="spec">' + rows.map(function (r) { return "<div><dt>" + r[0] + "</dt><dd>" + r[1] + "</dd></div>"; }).join("") + "</dl>" +
      '<div class="pdp__cta"><a class="btn btn--wa" href="' + J.link.whatsapp(ask) + '" rel="noopener">' + icon("message", 18) + "Ask about availability</a>" +
      '<a class="btn btn--primary" href="' + J.link.tel() + '">' + icon("phone", 18) + "Call now</a>" +
      '<a class="btn btn--ghost" href="' + url.page(backPage) + '">' + icon("arrowLeft", 18) + "Back to all products</a></div></div></div>" +
      '<div class="pdp__sections">' +
      '<div class="infobox"><h2>' + icon("info", 20) + "Typical use</h2><p>" + esc(p.usage) + "</p></div>" +
      '<div class="infobox"><h2>' + icon("package", 20) + "Storage instructions</h2><p>" + esc(S.storage(p)) + "</p></div></div>" +
      '<div style="margin-top:14px;display:grid;gap:12px">' + m.notice("safety") + m.notice("catalogue") +
      (p.sample ? '<p class="muted" style="font-size:.86rem">Listing details are being confirmed with the store. Please check the item before use.</p>' : "") + "</div>";

    function rail(title, list) {
      return list.length ? '<section class="related"><h2>' + esc(title) + "</h2>" + m.productGrid(list, "pgrid--4") + "</section>" : "";
    }
    html += rail("Similar brands", S.similarBrands(p, 4));
    html += rail("More from " + (p.manufacturer === "Various manufacturers" ? p.brand : p.manufacturer), S.fromManufacturer(p, 4));
    html += rail("Related products", S.related(p, 4));
    return html + "</div></section>";
  };
})();

/* ---- assets/js/modules/categories.js ---- */
/* MODULE 7: Categories (tiles, category banner, categories page, category page). */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var m = (J.m = J.m || {});
  var u = J.u, icon = J.icon, url = J.url, S = J.store, esc = u.esc;

  m.categoryTiles = function (list) {
    return '<div class="ctiles">' + list.map(function (c) {
      var n = S.categoryCount(c.slug);
      return '<a class="ctile" href="' + url.category(c.slug) + '" data-group="' + c.group + '"><span class="ctile__icon">' + icon(c.icon, 22) + "</span>" +
        "<span><span class=\"ctile__name\">" + esc(c.name) + '</span><span class="ctile__count" style="display:block">' + u.plural(n, "product") + "</span></span></a>";
    }).join("") + "</div>";
  };

  m.categoriesPage = function () {
    var out = m.pagehead({
      title: "Product categories",
      lead: "Biology, chemistry, physics and general laboratory items. Pick a category to see what we carry.",
      crumbs: [{ label: "Home", href: url.page("home") }, { label: "Categories" }]
    });
    out += '<section class="section"><div class="container">';
    S.groups().forEach(function (g, i) {
      out += '<div style="margin-top:' + (i ? 48 : 0) + 'px"><div class="section__head"><div><h2>' + esc(g.name) + "</h2><p>" + esc(g.description) + "</p></div>" + m.moreLink(url.subject(g.slug), "All " + g.name.toLowerCase()) + "</div>" +
        m.categoryTiles(S.categoriesIn(g.slug)) + "</div>";
    });
    return out + '<div style="margin-top:40px">' + m.notice("catalogue") + "</div></div></section>";
  };

  m.categoryPage = function (c) {
    var g = S.group(c.group);
    var sibs = S.categoriesIn(c.group).filter(function (x) { return x.slug !== c.slug; });
    var banner = '<section class="banner" data-group="' + c.group + '"><div class="container">' +
      m.crumbs([{ label: "Home", href: url.page("home") }, { label: "Categories", href: url.page("categories") }, { label: g.name, href: url.subject(g.slug) }, { label: c.name }]) +
      '<div class="banner__inner"><span class="banner__icon">' + icon(c.icon, 44) + '</span><div><h1>' + esc(c.name) + "</h1><p>" + esc(c.description) + "</p>" +
      (sibs.length ? '<div class="chips" aria-label="Other ' + esc(g.name) + ' categories">' + sibs.slice(0, 7).map(function (x) {
        return '<a class="chip" href="' + url.category(x.slug) + '">' + esc(x.name) + "</a>";
      }).join("") + "</div>" : "") + "</div></div></div></section>";
    return banner + '<section class="section section--tight"><div class="container">' +
      m.catalogue({ scope: "all", category: c.slug }, {}) +
      '<div style="margin-top:30px">' + m.notice("catalogue") + "</div></div></section>";
  };

  var GROUP_ICON = { biology: "microscope", chemistry: "flask", physics: "atom", laboratory: "package" };

  /* Four large links to the subjects, as on the original site's menu. */
  m.subjectTiles = function () {
    return '<section class="section section--tight" aria-label="Subjects"><div class="container"><div class="subjects">' + S.groups().map(function (g) {
      var n = S.products().filter(function (p) { return S.groupOf(p) === g.slug; }).length;
      return '<a class="subject" href="' + url.subject(g.slug) + '" data-group="' + g.slug + '"><span class="subject__icon">' + icon(GROUP_ICON[g.slug], 26) + "</span>" +
        "<strong>" + esc(g.name) + "</strong><span>" + esc(u.truncate(g.description, 78)) + "</span><em>" + u.plural(n, "product") + "</em></a>";
    }).join("") + "</div></div></section>";
  };

  /* One page per subject: Biology, Chemistry, Physics, General laboratory items. */
  m.subjectPage = function (g) {
    var cats = S.categoriesIn(g.slug);
    var banner = '<section class="banner" data-group="' + g.slug + '"><div class="container">' +
      m.crumbs([{ label: "Home", href: url.page("home") }, { label: "Categories", href: url.page("categories") }, { label: g.name }]) +
      '<div class="banner__inner"><span class="banner__icon">' + icon(GROUP_ICON[g.slug], 44) + "</span><div><h1>" + esc(g.name) + "</h1><p>" + esc(g.description) + "</p>" +
      '<div class="chips" aria-label="' + esc(g.name) + ' categories">' + cats.map(function (x) {
        return '<a class="chip" href="' + url.category(x.slug) + '">' + esc(x.name) + "</a>";
      }).join("") + "</div></div></div></div></section>";
    return banner + '<section class="section section--tight"><div class="container">' +
      m.catalogue({ scope: g.slug }, {}) + '<div style="margin-top:30px;display:grid;gap:12px">' + m.notice("safety") + m.notice("catalogue") + "</div></div></section>";
  };
})();

/* ---- assets/js/modules/brands.js ---- */
/* MODULE 8: Brand directory (A–Z directory, brand search, brand pages). */
(function () {
  var J = (window.JAICO = window.JAICO || {});
  var m = (J.m = J.m || {});
  var u = J.u, icon = J.icon, url = J.url, S = J.store, esc = u.esc;

  function tone(name) { var n = 0; for (var i = 0; i < name.length; i++) n += name.charCodeAt(i); return n % 5; }
  function initials(name) {
    var w = name.replace(/[^A-Za-z0-9 -]/g, "").split(/[ -]+/).filter(Boolean);
    return (w.length > 1 ? w[0][0] + w[1][0] : name.slice(0, 2)).toUpperCase();
  }
  m.brandMark = function (b, large) {
    if (b.logo) return '<span class="mono' + (large ? " mono--lg" : "") + '" style="background:#fff;border:1px solid var(--line)"><img src="' + url.asset(b.logo) + '" alt="' + esc(b.name) + ' logo" width="' + (large ? 64 : 36) + '" height="' + (large ? 64 : 36) + '" loading="lazy"></span>';
    return '<span class="mono' + (large ? " mono--lg" : "") + '" data-tone="' + tone(b.name) + '" aria-hidden="true">' + esc(initials(b.name)) + "</span>";
  };

  m.brandTile = function (b) {
    var n = S.brandCount(b.name);
    return '<a class="btile" href="' + url.brand(b.name) + '">' + m.brandMark(b) + "<span><strong>" + esc(b.name) + "</strong><small>" + u.plural(n, "product") + "</small></span></a>";
  };

  m.brandCard = function (b) {
    var n = S.brandCount(b.name);
    return '<article class="bcard" data-brand="' + esc((b.name + " " + b.company).toLowerCase()) + '"><div class="bcard__head">' + m.brandMark(b) +
      "<div><h3>" + esc(b.name) + '</h3><p class="bcard__company">' + esc(b.company) + "</p></div></div><p>" + esc(b.short) + "</p>" +
      '<div class="bcard__foot"><span class="muted" style="font-size:.88rem">' + u.plural(n, "product") + "</span>" +
      '<a class="btn btn--soft btn--sm" href="' + url.brand(b.name) + '">View products<span class="sr-only"> from ' + esc(b.name) + "</span></a></div></article>";
  };

  m.brandsPage = function () {
    var brands = S.brands(), groups = {};
    brands.forEach(function (b) { var l = b.name[0].toUpperCase(); (groups[l] = groups[l] || []).push(b); });
    var letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
    var bar = '<nav class="azbar" aria-label="Jump to letter">' + letters.map(function (l) {
      return groups[l] ? '<a href="#letter-' + l + '">' + l + "</a>" : '<span aria-hidden="true">' + l + "</span>";
    }).join("") + "</nav>";
    var body = letters.filter(function (l) { return groups[l]; }).map(function (l) {
      return '<section class="azgroup" id="letter-' + l + '" data-letter><h2>' + l + '</h2><div class="grid grid--wide">' + groups[l].map(m.brandCard).join("") + "</div></section>";
    }).join("");
    return m.pagehead({
      title: "Brands and manufacturers",
      lead: "Brands whose products appear in our directory, with the company behind each one.",
      crumbs: [{ label: "Home", href: url.page("home") }, { label: "Brands" }]
    }) + '<section class="section section--tight"><div class="container">' +
      '<form class="sbox" role="search" data-brandsearch onsubmit="return false"><div class="sbox__field">' + icon("search", 22) +
      '<label class="sr-only" for="brand-q">Search brands</label><input id="brand-q" class="sbox__input" type="search" placeholder="Search brands or companies…" autocomplete="off"></div></form>' +
      bar + '<p class="sr-only" role="status" aria-live="polite" data-brand-live></p><div data-brandlist>' + body + "</div>" +
      '<div class="empty" data-brand-empty hidden style="margin-top:30px"><h3>No brand matches your search</h3><p>Try another spelling, or call us to ask about a brand that is not listed.</p></div>' +
      '<div style="margin-top:36px">' + m.notice("catalogue") + "</div></div></section>";
  };

  m.brandPage = function (b) {
    var list = S.productsByBrand(b.name);
    return '<section class="pagehead"><div class="container">' +
      m.crumbs([{ label: "Home", href: url.page("home") }, { label: "Brands", href: url.page("brands") }, { label: b.name }]) +
      '<div style="display:flex;align-items:center;gap:20px;flex-wrap:wrap">' + m.brandMark(b, true) + "<div><h1>" + esc(b.name) + '</h1><p class="lead" style="margin-top:6px">' + esc(b.company) + "</p></div></div>" +
      '<p class="lead" style="margin-top:16px">' + esc(b.short) + "</p></div></section>" +
      '<section class="section section--tight"><div class="container"><h2 style="font-size:1.5rem;margin-bottom:18px">' + u.plural(list.length, "product") + " from " + esc(b.name) + "</h2>" +
      (list.length ? m.productGrid(list) : '<div class="empty"><h3>No products listed yet</h3><p>Call or message us to ask about this brand.</p></div>') +
      '<div style="margin-top:30px">' + m.notice("catalogue") + "</div></div></section>";
  };
})();

